{
  "name": "@doyzheng/ezllm-workbuddy-pool-auth",
  "version": "0.1.7",
  "description": "WorkBuddy 多账号池插件：账号管理、每日自动签到（中断续跑）、积分查询、登录态续期与按 session 轮转的 OpenAI 兼容转发；自带设置 UI",
  "license": "MIT",
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "type": "module",
  "main": "dist/index.mjs",
  "exports": {
    ".": "./dist/index.mjs",
    "./service": "./dist/service.mjs"
  },
  "ezllmPlugin": true,
  "ezllm": {
    "id": "workbuddy",
    "service": {
      "entry": "dist/service.mjs",
      "health": "/health",
      "timeoutMs": 15000
    },
    "settings": {
      "ui": "ui/index.html",
      "title": "WorkBuddy 账号池",
      "api": true
    },
    "authActions": {
      "workbuddy-pool": {
        "type": "settings",
        "label": "账号管理"
      }
    }
  },
  "files": [
    "dist/index.mjs",
    "dist/service.mjs",
    "ui",
    "README.md"
  ],
  "repository": {
    "type": "git",
    "url": "https://gitee.com/doyzheng/ezllm",
    "directory": "packages/plugins/workbuddy-pool"
  },
  "keywords": [
    "ezllm",
    "plugin",
    "workbuddy",
    "codebuddy",
    "opencode"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "ezn vite build && ezn vite build --mode service",
    "check:types": "ezn tsc --noEmit",
    "test": "ezn vitest run"
  },
  "devDependencies": {
    "@magpie-community/opencode-workbuddy-auth": "~0.2.36",
    "@types/node": "^22.10.0",
    "typescript": "^7.0.2",
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  }
}

/* WorkBuddy 插件自带设置页（原生 JS；无外部依赖）。
 *
 * 页面由插件自己的 HTTP service 托管（宿主 `/plugin/<id>/<service>/ui/` 代理）；
 * UI 与 service 同源，API 固定取 `../api/`，不需要管理台 token、也没有跨域。
 */
(function () {
  "use strict";

  var API = new URL("../api/", location.href).pathname;

  var els = {
    alert: document.getElementById("alert"),
    panel: document.getElementById("panel"),
    total: document.getElementById("total"),
    count: document.getElementById("count"),
    disabledTag: document.getElementById("disabled-tag"),
    disabledCount: document.getElementById("disabled-count"),
    updatedTag: document.getElementById("updated-tag"),
    updatedAt: document.getElementById("updated-at"),
    rows: document.getElementById("rows"),
    empty: document.getElementById("empty"),
    autoCheckin: document.getElementById("auto-checkin"),
    checkinDisabled: document.getElementById("checkin-disabled-accounts"),
    rotateTurns: document.getElementById("rotate-turns"),
    minCredits: document.getElementById("min-credits"),
    settingsModal: document.getElementById("settings-modal"),
    settingsOpen: document.getElementById("settings-open"),
    settingsClose: document.getElementById("settings-close"),
    settingsCancel: document.getElementById("settings-cancel"),
    settingsSave: document.getElementById("settings-save"),
    refresh: document.getElementById("refresh"),
    checkinAll: document.getElementById("checkin-all"),
    testAll: document.getElementById("test-all"),
    addAccount: document.getElementById("add-account"),
    modal: document.getElementById("add-modal"),
    modalClose: document.getElementById("modal-close"),
    modalCancel: document.getElementById("modal-cancel"),
    importText: document.getElementById("import-text"),
    importSubmit: document.getElementById("import-submit"),
    loginStart: document.getElementById("login-start"),
    loginState: document.getElementById("login-state"),
    usageModal: document.getElementById("usage-modal"),
    usageClose: document.getElementById("usage-close"),
    usageTitle: document.getElementById("usage-title"),
    usageSummary: document.getElementById("usage-summary"),
    usageChart: document.getElementById("usage-chart"),
    usageRows: document.getElementById("usage-rows"),
    usageEmpty: document.getElementById("usage-empty"),
    toast: document.getElementById("toast"),
  };

  var accounts = [];
  var settings = {
    autoCheckin: true,
    checkinDisabledAccounts: true,
    checkinHours: [9],
    rotateAfterTurns: 100,
    minCreditsToUse: 50,
  };
  var busy = false;
  var loginPoll = null;
  var toastTimer = null;

  function esc(value) {
    return String(value == null ? "" : value).replace(/[&<>"']/g, function (ch) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch];
    });
  }

  function fmtNum(value) {
    var n = Number(value);
    return Number.isFinite(n) ? Math.round(n).toLocaleString("zh-CN") : "-";
  }

  function timeText(ms, withSeconds) {
    var n = Number(ms);
    if (!Number.isFinite(n) || n <= 0) return "-";
    var d = new Date(n);
    var p = function (x) {
      return String(x).padStart(2, "0");
    };
    var text = p(d.getMonth() + 1) + "-" + p(d.getDate()) + " " + p(d.getHours()) + ":" + p(d.getMinutes());
    return withSeconds ? text + ":" + p(d.getSeconds()) : text;
  }

  function toast(message, isError) {
    els.toast.textContent = message;
    els.toast.className = "toast" + (isError ? " is-error" : "");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      els.toast.className = "toast hidden";
    }, 2400);
  }

  function showAlert(message) {
    els.alert.textContent = message;
    els.alert.className = "alert";
  }

  function hideAlert() {
    els.alert.textContent = "";
    els.alert.className = "alert hidden";
  }

  async function api(path, options) {
    var opts = options || {};
    var res = await fetch(API + path, {
      method: opts.method || "GET",
      headers: { "Content-Type": "application/json" },
      body: opts.body,
    });
    var text = await res.text();
    var data = {};
    try {
      data = text ? JSON.parse(text) : {};
    } catch {
      throw new Error("接口返回不是 JSON：" + text.slice(0, 120));
    }
    if (!res.ok) throw new Error(data.error || "HTTP " + res.status);
    return data;
  }

  async function load() {
    els.refresh.disabled = true;
    try {
      var results = await Promise.all([api("accounts"), api("settings")]);
      accounts = Array.isArray(results[0].accounts) ? results[0].accounts : [];
      settings = results[1].settings || settings;
      hideAlert();
      render();
    } catch (err) {
      showAlert("加载失败：" + (err && err.message ? err.message : String(err)));
    } finally {
      els.refresh.disabled = false;
    }
  }

  function render() {
    els.panel.className = "card";
    var remain = 0;
    var disabled = 0;
    var latest = 0;
    accounts.forEach(function (a) {
      if (a.credits) remain += Number(a.credits.remain) || 0;
      if (a.disabled) disabled++;
      if (a.credits && a.credits.at > latest) latest = a.credits.at;
    });
    els.total.textContent = fmtNum(remain);
    els.count.textContent = String(accounts.length);
    els.disabledCount.textContent = String(disabled);
    els.disabledTag.className = disabled > 0 ? "tag" : "tag hidden";
    els.updatedTag.className = latest > 0 ? "tag tag-muted" : "tag tag-muted hidden";
    els.updatedAt.textContent = latest > 0 ? timeText(latest) : "-";
    els.empty.className = accounts.length === 0 ? "empty" : "empty hidden";

    els.rows.innerHTML = accounts
      .map(function (a) {
        var credit = a.credits
          ? '<button class="link-btn" data-action="usage" data-uid="' +
            esc(a.uid) +
            '" data-nick="' +
            esc(a.nickname) +
            '" title="查看积分使用记录">' +
            fmtNum(a.credits.remain) +
            " / " +
            fmtNum(a.credits.size) +
            "</button>"
          : '<span class="pill pill-muted">未查询</span>';
        var streak =
          a.checkin && a.checkin.status === "done"
            ? String(a.checkin.streakDays) + " 天"
            : '<span class="pill pill-muted">-</span>';
        var today = '<span class="pill pill-muted">未签</span>';
        if (a.checkin && a.checkin.status === "done") {
          today =
            '<span class="pill pill-success">' +
            (a.checkin.credit > 0 ? "+" + String(a.checkin.credit) : "已签") +
            "</span>";
        } else if (a.checkin && a.checkin.status === "failed") {
          today = '<span class="pill pill-danger" title="' + esc(a.checkin.lastError || "签到失败") + '">失败</span>';
        }
        var expiry = a.expiresAt > 0 ? timeText(a.expiresAt) : '<span class="pill pill-muted">未知</span>';
        var lastCheckin =
          a.lastCheckinAt > 0 ? timeText(a.lastCheckinAt, true) : '<span class="pill pill-muted">-</span>';
        var cooling = a.cooldownUntil > Date.now();
        var health;
        if (cooling && a.cooldownKind === "auth") {
          health =
            '<span class="pill pill-danger" title="' +
            esc(a.cooldownReason || "凭据已失效，需重新登录") +
            '">需重新登录</span>';
        } else if (cooling) {
          health =
            '<span class="pill pill-warn" title="' +
            esc(a.cooldownReason || "上游 429，冷却中") +
            '">冷却至 ' +
            timeText(a.cooldownUntil) +
            "</span>";
        } else if (a.healthy) {
          health = '<span class="pill pill-success">正常</span>';
        } else {
          health =
            '<span class="pill pill-danger" title="连续失败 ' + String(a.failures) + ' 次，已暂停轮转">异常</span>';
        }
        var disabledTag = a.disabled ? ' <span class="pill pill-muted">已停用</span>' : "";
        var domainLine = a.domain
          ? '<div class="domain" title="账号登录域名（签到/计费按它）">' + esc(a.domain) + "</div>"
          : "";
        return (
          '<tr class="' +
          (a.disabled ? "is-disabled" : "") +
          '">' +
          '<td><div class="nick">' +
          esc(a.nickname) +
          disabledTag +
          '</div><div class="uid" title="' +
          esc(a.uid) +
          '">' +
          esc(a.uid) +
          "</div>" +
          domainLine +
          "</td>" +
          "<td>" +
          credit +
          "</td>" +
          '<td class="usage-num">' +
          (Number(a.todayConsumed) > 0 ? fmtDec(a.todayConsumed) : "0") +
          "</td>" +
          "<td>" +
          streak +
          "</td>" +
          "<td>" +
          today +
          "</td>" +
          "<td>" +
          lastCheckin +
          "</td>" +
          "<td>" +
          expiry +
          "</td>" +
          "<td>" +
          health +
          "</td>" +
          '<td><div class="ops">' +
          '<button class="btn btn-sm" data-action="test" data-uid="' +
          esc(a.uid) +
          '">测试</button>' +
          '<button class="btn btn-sm" data-action="checkin" data-uid="' +
          esc(a.uid) +
          '">签到</button>' +
          '<button class="btn btn-sm" data-action="' +
          (a.disabled ? "enable" : "disable") +
          '" data-uid="' +
          esc(a.uid) +
          '">' +
          (a.disabled ? "启用" : "停用") +
          "</button>" +
          '<button class="btn btn-sm btn-danger" data-action="delete" data-uid="' +
          esc(a.uid) +
          '" data-nick="' +
          esc(a.nickname) +
          '">删除</button>' +
          "</div></td>" +
          "</tr>"
        );
      })
      .join("");
  }

  async function run(button, task) {
    if (busy) return;
    busy = true;
    if (button) button.classList.add("is-loading");
    var buttons = document.querySelectorAll("button");
    buttons.forEach(function (b) {
      b.disabled = true;
    });
    try {
      await task();
    } catch (err) {
      toast(err && err.message ? err.message : String(err), true);
    } finally {
      busy = false;
      buttons.forEach(function (b) {
        b.disabled = false;
      });
      if (button) {
        button.disabled = false;
        button.classList.remove("is-loading");
      }
    }
  }

  els.rows.addEventListener("click", function (event) {
    var target = event.target;
    if (!(target instanceof HTMLElement)) return;
    var action = target.getAttribute("data-action");
    var uid = target.getAttribute("data-uid") || "";
    if (!action || !uid) return;
    if (action === "usage") {
      void openUsage(uid, target.getAttribute("data-nick") || uid);
      return;
    }
    if (action === "test") {
      void run(target, async function () {
        var result = await api("accounts/" + encodeURIComponent(uid) + "/test", { method: "POST" });
        toast(
          result.ok
            ? "测试通过（HTTP " + String(result.status) + "，" + String(result.message || "可用") + "）"
            : "测试失败：" + String(result.message || "HTTP " + String(result.status)),
          !result.ok,
        );
        await load();
      });
    } else if (action === "checkin") {
      void run(target, async function () {
        var result = await api("accounts/" + encodeURIComponent(uid) + "/checkin", { method: "POST" });
        if (result.queued) {
          toast("已排入签到队列，稍后自动刷新");
          await load();
          return;
        }
        var o = result.outcome || {};
        if (o.ok && o.already) toast("今日已签到");
        else if (o.ok) toast("签到成功 +" + String(o.credit || 0) + " 积分");
        else toast(o.error || "签到失败", true);
        await load();
      });
    } else if (action === "disable" || action === "enable") {
      void run(target, async function () {
        await api("accounts/" + encodeURIComponent(uid) + "/" + action, { method: "POST" });
        toast(action === "disable" ? "已停用" : "已启用");
        await load();
      });
    } else if (action === "delete") {
      var nick = target.getAttribute("data-nick") || uid;
      if (!window.confirm("删除账号 " + nick + "？账号授权文件会从本机移除，不可撤销。")) return;
      void run(target, async function () {
        await api("accounts/" + encodeURIComponent(uid), { method: "DELETE" });
        toast("已删除 " + nick);
        await load();
      });
    }
  });

  // —— 积分使用记录（每账号弹窗）——
  var usageUid = "";

  function closeUsage() {
    usageUid = "";
    els.usageModal.className = "modal hidden";
  }

  async function openUsage(uid, nick) {
    usageUid = uid;
    els.usageTitle.textContent = nick + " · 积分使用记录（近 30 天）";
    els.usageModal.className = "modal";
    els.usageSummary.innerHTML = "";
    els.usageChart.innerHTML = "";
    els.usageEmpty.className = "empty hidden";
    els.usageRows.innerHTML = '<tr><td colspan="7" class="usage-loading">加载中…</td></tr>';
    try {
      var data = await api("usage?uid=" + encodeURIComponent(uid) + "&days=30");
      if (usageUid !== uid) return; // 弹窗已切到别的账号
      renderUsage(Array.isArray(data.daily) ? data.daily : []);
    } catch (err) {
      if (usageUid !== uid) return;
      els.usageRows.innerHTML = "";
      els.usageEmpty.textContent = "加载失败：" + (err && err.message ? err.message : String(err));
      els.usageEmpty.className = "empty";
    }
  }

  function fmtDec(value) {
    var n = Number(value);
    if (!Number.isFinite(n)) return "-";
    return n.toLocaleString("zh-CN", { maximumFractionDigits: 2 });
  }

  function fmtTokens(value) {
    var n = Number(value) || 0;
    if (n >= 1e6) return (n / 1e6).toFixed(1) + "M";
    if (n >= 1e3) return (n / 1e3).toFixed(1) + "k";
    return String(Math.round(n));
  }

  function sumOf(rows, key) {
    return rows.reduce(function (acc, row) {
      return acc + (Number(row[key]) || 0);
    }, 0);
  }

  function renderUsage(daily) {
    var today = daily.length > 0 ? daily[daily.length - 1] : null;
    els.usageSummary.innerHTML =
      '<span class="tag tag-primary">今日消耗 <b>' +
      fmtDec(today ? today.consumed : 0) +
      "</b></span>" +
      '<span class="tag">7 天 <b>' +
      fmtDec(sumOf(daily.slice(-7), "consumed")) +
      "</b></span>" +
      '<span class="tag">30 天 <b>' +
      fmtDec(sumOf(daily, "consumed")) +
      "</b></span>" +
      '<span class="tag">30 天发放 <b>' +
      fmtDec(sumOf(daily, "added")) +
      "</b></span>" +
      '<span class="tag tag-muted">请求 <b>' +
      String(sumOf(daily, "requests")) +
      "</b></span>";

    var chart = daily.slice(-14);
    var peak = Math.max.apply(
      null,
      chart
        .map(function (row) {
          return Number(row.consumed) || 0;
        })
        .concat([0.0001]),
    );
    els.usageChart.innerHTML = chart
      .map(function (row) {
        var height = Math.max(2, Math.round(((Number(row.consumed) || 0) / peak) * 100));
        return (
          '<div class="usage-bar" style="height:' +
          String(height) +
          '%" title="' +
          esc(row.day) +
          "：" +
          fmtDec(row.consumed) +
          " 积分 · " +
          String(row.requests) +
          ' 请求"></div>'
        );
      })
      .join("");

    var rows = daily
      .slice()
      .reverse()
      .filter(function (row) {
        return row.sampledAt > 0 || row.requests > 0;
      });
    if (rows.length === 0) {
      els.usageRows.innerHTML = "";
      els.usageEmpty.textContent = "暂无记录：积分每 10 分钟采样一次，转发请求才记 token";
      els.usageEmpty.className = "empty";
      return;
    }
    els.usageEmpty.className = "empty hidden";
    els.usageRows.innerHTML = rows
      .map(function (row) {
        var consumed = Number(row.consumed) || 0;
        var added = Number(row.added) || 0;
        var models = Object.keys(row.byModel || {})
          .sort(function (a, b) {
            var ma = row.byModel[a] || {};
            var mb = row.byModel[b] || {};
            return (mb.credit || 0) - (ma.credit || 0) || (mb.requests || 0) - (ma.requests || 0);
          })
          .slice(0, 2)
          .map(function (name) {
            var m = row.byModel[name];
            return esc(name) + (m.credit > 0 ? " " + fmtDec(m.credit) : " ×" + String(m.requests));
          })
          .join("、");
        // 消耗有变化但本机没转发过：说明是其它客户端在用这个账号
        var modelCell =
          models !== "" ? models : consumed > 0 ? '<span class="pill pill-muted">其它客户端</span>' : "-";
        return (
          "<tr>" +
          '<td class="usage-day">' +
          esc(String(row.day).slice(5)) +
          "</td>" +
          '<td class="usage-num">' +
          (consumed > 0 ? fmtDec(consumed) : "0") +
          "</td>" +
          '<td class="usage-num">' +
          (added > 0 ? "+" + fmtDec(added) : "-") +
          "</td>" +
          '<td class="usage-num">' +
          (row.remainEnd == null ? "-" : fmtDec(row.remainEnd)) +
          "</td>" +
          '<td class="usage-num">' +
          (row.requests > 0 ? String(row.requests) : "-") +
          "</td>" +
          '<td class="usage-num">' +
          (row.requests > 0 ? fmtTokens(row.input) + " / " + fmtTokens(row.output) : "-") +
          "</td>" +
          "<td>" +
          modelCell +
          "</td>" +
          "</tr>"
        );
      })
      .join("");
  }

  els.usageClose.addEventListener("click", closeUsage);
  els.usageModal.addEventListener("click", function (event) {
    if (event.target === els.usageModal) closeUsage();
  });

  // 网关放行 marker：provider 行改成「账号管理」后没有登录按钮了；若宿主里的 marker 丢失
  // （activate 写失败/被手工清掉），转发会一直报「尚未登录」。刷新时顺带补写一次。
  // API 形如 <前缀>/plugin/<id>/<service>/api/：宿主根 = 去掉 plugin/… 后的前缀。
  // 直连宿主时是 "/"，经管理台反代（/api/plugin-ui/）时前缀跟着变，两种形态都不写死。
  async function syncGatewayLogin() {
    try {
      var hostRoot = API.replace(/plugin\/[^/]+\/[^/]+\/api\/$/, "");
      var res = await fetch(hostRoot + "login/workbuddy-pool", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key: "pool" }),
      });
      var data = await res.json().catch(function () {
        return {};
      });
      return res.ok && (data.state === "success" || data.signedIn === true);
    } catch (err) {
      return false;
    }
  }

  els.refresh.addEventListener("click", function () {
    void run(els.refresh, async function () {
      // 先显示现有缓存，再补写宿主放行 marker、触发后台积分查询。
      // 积分查询串行查全池可能超过反代超时：服务端立即返回，前端分两次回读（3s 部分 / 8s 最终）。
      await load();
      var synced = await syncGatewayLogin();
      await api("refresh-credits", { method: "POST" });
      toast(synced ? "正在查询最新积分…" : "网关登录态同步失败（不影响账号数据），正在查询最新积分…", !synced);
      setTimeout(function () {
        void load();
      }, 3000);
      setTimeout(function () {
        void load();
      }, 8000);
    });
  });

  els.checkinAll.addEventListener("click", function () {
    void run(els.checkinAll, async function () {
      var result = await api("checkin-all", { method: "POST" });
      if (result.queued) {
        toast("已排入签到队列，稍后自动刷新");
        await load();
        return;
      }
      toast(
        "签到完成：成功 " + String(result.done || 0) + "，失败 " + String(result.failed || 0),
        Number(result.failed) > 0,
      );
      await load();
    });
  });

  els.testAll.addEventListener("click", function () {
    var label = els.testAll.textContent;
    void run(els.testAll, async function () {
      var passed = 0;
      var failed = 0;
      try {
        for (var i = 0; i < accounts.length; i++) {
          els.testAll.textContent = "测试 " + String(i + 1) + "/" + String(accounts.length);
          try {
            var result = await api("accounts/" + encodeURIComponent(accounts[i].uid) + "/test", { method: "POST" });
            if (result.ok) passed++;
            else failed++;
          } catch (err) {
            failed++;
          }
        }
      } finally {
        els.testAll.textContent = label;
      }
      await load();
      toast("测试完成：可用 " + String(passed) + " 个，失败 " + String(failed) + " 个", failed > 0);
    });
  });

  els.addAccount.addEventListener("click", openModal);

  // —— 设置弹窗（自动签到 / 停用账号签到 / 长对话换号）——
  // 控件只改本地值，点「保存」才落盘（避免误点立即生效）；关闭不保存。
  function fillSettingsForm() {
    els.autoCheckin.checked = settings.autoCheckin !== false;
    els.checkinDisabled.checked = settings.checkinDisabledAccounts !== false;
    els.rotateTurns.value = String(settings.rotateAfterTurns == null ? 100 : settings.rotateAfterTurns);
    els.minCredits.value = String(settings.minCreditsToUse == null ? 50 : settings.minCreditsToUse);
  }

  function closeSettings() {
    els.settingsModal.className = "modal hidden";
  }

  els.settingsOpen.addEventListener("click", function () {
    fillSettingsForm();
    els.settingsModal.className = "modal";
  });
  els.settingsClose.addEventListener("click", closeSettings);
  els.settingsCancel.addEventListener("click", closeSettings);
  els.settingsModal.addEventListener("click", function (event) {
    if (event.target === els.settingsModal) closeSettings();
  });

  els.settingsSave.addEventListener("click", function () {
    var raw = els.rotateTurns.value.trim();
    var rotate = raw === "" ? 0 : Math.trunc(Number(raw));
    if (!Number.isFinite(rotate) || rotate < 0 || rotate > 10000) {
      toast("长对话换号需要 0–10000 的整数", true);
      els.rotateTurns.focus();
      return;
    }
    var minRaw = els.minCredits.value.trim();
    var minCredits = minRaw === "" ? 0 : Math.trunc(Number(minRaw));
    if (!Number.isFinite(minCredits) || minCredits < 0 || minCredits > 1000000) {
      toast("选号最低积分需要 0–1000000 的整数", true);
      els.minCredits.focus();
      return;
    }
    void run(els.settingsSave, async function () {
      var result = await api("settings", {
        method: "PUT",
        body: JSON.stringify({
          autoCheckin: els.autoCheckin.checked,
          checkinDisabledAccounts: els.checkinDisabled.checked,
          rotateAfterTurns: rotate,
          minCreditsToUse: minCredits,
        }),
      });
      settings = result.settings || settings;
      closeSettings();
      toast("设置已保存");
    });
  });

  // —— 添加账号 ——
  function openModal() {
    els.modal.className = "modal";
    els.importText.value = "";
    els.loginState.textContent = "";
    switchTab("import");
  }

  function closeModal() {
    els.modal.className = "modal hidden";
    stopLoginPoll();
  }

  function switchTab(name) {
    document.querySelectorAll(".tab").forEach(function (tab) {
      tab.classList.toggle("is-active", tab.getAttribute("data-tab") === name);
    });
    document.getElementById("pane-import").className = name === "import" ? "pane" : "pane hidden";
    document.getElementById("pane-browser").className = name === "browser" ? "pane" : "pane hidden";
  }

  document.querySelectorAll(".tab").forEach(function (tab) {
    tab.addEventListener("click", function () {
      switchTab(tab.getAttribute("data-tab"));
    });
  });

  els.addAccount.addEventListener("click", openModal);
  els.modalClose.addEventListener("click", closeModal);
  els.modalCancel.addEventListener("click", closeModal);
  els.modal.addEventListener("click", function (event) {
    if (event.target === els.modal) closeModal();
  });

  els.importSubmit.addEventListener("click", function () {
    void run(els.importSubmit, async function () {
      var raw = els.importText.value.trim();
      if (raw === "") throw new Error("请先粘贴授权文件 JSON");
      try {
        JSON.parse(raw);
      } catch {
        throw new Error("不是合法 JSON");
      }
      var result = await api("accounts/import", { method: "POST", body: raw });
      toast("已导入账号 " + String(result.uid || ""));
      closeModal();
      await load();
    });
  });

  function stopLoginPoll() {
    if (loginPoll) {
      clearInterval(loginPoll);
      loginPoll = null;
    }
  }

  els.loginStart.addEventListener("click", function () {
    void run(els.loginStart, async function () {
      // 同步开窗（用户手势内），再用接口返回的 authUrl 导航，避免被弹窗拦截
      var win = window.open("about:blank", "_blank");
      var started = await api("login/start", { method: "POST" });
      if (!started.authUrl) {
        if (win) win.close();
        throw new Error(started.error || "上游未返回登录页");
      }
      if (win) win.location.href = started.authUrl;
      else els.loginState.textContent = "弹窗被拦截，请手动打开：" + started.authUrl;
      els.loginState.textContent = "等待浏览器完成登录…";
      stopLoginPoll();
      loginPoll = setInterval(function () {
        void (async function () {
          try {
            var result = await api("login/status?state=" + encodeURIComponent(started.state));
            if (result.status === "pending") return;
            stopLoginPoll();
            if (result.status === "success") {
              toast("登录成功：" + (result.nickname || result.uid || ""));
              closeModal();
              await load();
            } else {
              els.loginState.textContent = "登录失败：" + (result.error || "未知错误");
            }
          } catch {
            /* 下一轮再试 */
          }
        })();
      }, 2000);
    });
  });

  void load();
  // 页面可见时每分钟兜底刷新一次（签到由后台调度；这里只更新展示）
  setInterval(function () {
    if (document.visibilityState === "visible" && !busy) void load();
  }, 60000);
})();
